select count(fmcs1_0.id) from fixture_match_collect_state fmcs1_0 join fixture_core f1_0 on f1_0.id=fmcs1_0.fixture_core_id left join league_core l1_0 on l1_0.id=f1_0.league_id left join league_season_core ls1_0 on ls1_0.id=f1_0.league_season_id left join league_core l2_0 on l2_0.id=ls1_0.league_core_id where (l2_0.uid=? or l1_0.uid=?) and fmcs1_0.match_collect_status in (?,?,?,?,?,?)
